  function renderProductBuildTracker(tracker) {
    return `
      <section class="product-build-tracker">
        <div class="info-head">
          <div>
            <span class="metric-label">Build tracker</span>
            <h3>Where PursuitDesk stands now</h3>
          </div>
          <span>${escapeHtml(tracker.version)}</span>
        </div>
        <div class="build-tracker-hero">
          <div>
            <span>Current phase</span>
            <strong>${escapeHtml(tracker.phase)}</strong>
            <p>${escapeHtml(tracker.summary)}</p>
          </div>
          <div>
            <span>Build lane</span>
            <strong>${escapeHtml(tracker.lane)}</strong>
            <p>${escapeHtml(tracker.pace)}</p>
          </div>
        </div>
        <div class="build-track-grid">
          ${tracker.tracks
            .map(
              ([label, value, note, tone]) => `
                <article class="build-track-card tone-${escapeHtml(tone)}">
                  <div>
                    <span>${escapeHtml(label)}</span>
                    <strong>${escapeHtml(String(value))}%</strong>
                  </div>
                  <i><b style="width: ${Math.max(0, Math.min(100, Number(value)))}%"></b></i>
                  <p>${escapeHtml(note)}</p>
                </article>
              `,
            )
            .join("")}
        </div>
        <div class="build-phase-grid">
          <article>
            <div class="info-head compact">
              <div>
                <span class="metric-label">Phase map</span>
                <h3>Done, active, next</h3>
              </div>
            </div>
            <div class="build-phase-list">
              ${tracker.phases
                .map(
                  ([no, label, status, note]) => `
                    <div class="build-phase-row status-${escapeHtml(status.toLowerCase().replaceAll(" ", "-"))}">
                      <span>${escapeHtml(no)}</span>
                      <strong>${escapeHtml(label)}</strong>
                      <em>${escapeHtml(status)}</em>
                      <small>${escapeHtml(note)}</small>
                    </div>
                  `,
                )
                .join("")}
            </div>
          </article>
          <article>
            <div class="info-head compact">
              <div>
                <span class="metric-label">Next builds</span>
                <h3>Roadmap queue</h3>
              </div>
            </div>
            <div class="build-next-list">
              ${tracker.nextBuilds
                .map(
                  ([version, title, note]) => `
                    <div>
                      <span>${escapeHtml(version)}</span>
                      <strong>${escapeHtml(title)}</strong>
                      <p>${escapeHtml(note)}</p>
                    </div>
                  `,
                )
                .join("")}
            </div>
          </article>
          <article>
            <div class="info-head compact">
              <div>
                <span class="metric-label">Production blockers</span>
                <h3>Before real SaaS pilot</h3>
              </div>
            </div>
            <div class="build-blocker-list">
              ${tracker.blockers.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}
            </div>
          </article>
        </div>
      </section>
    `;
  }

  function renderBuildPhasePage() {
    const commandModel = buildCommandCenterModel();
    const tracker = buildProductBuildTracker();
    const doneCount = tracker.phases.filter(([, , status]) => status === "Done").length;
    const activeCount = tracker.phases.filter(([, , status]) => status === "Active").length;
    const mostlyDoneCount = tracker.phases.filter(([, , status]) => status === "Mostly done").length;
    return `
      <section class="build-phase-workspace">
        <section class="build-phase-console">
          <div>
            <span class="panel-label">Admin build room</span>
            <h2>Keep the roadmap out of the operating screen.</h2>
            <p>Command Center stays focused on daily work. Build Phase keeps the product roadmap, current milestone, next versions, production blockers, backend artifact packs, and SaaS-readiness percentages in one admin-only place.</p>
            <div class="command-actions">
              <button class="secondary-btn" type="button" data-view="Command">Open command center</button>
              <button class="ghost-btn" type="button" data-view="Reports">Open reports</button>
              <button class="ghost-btn" type="button" data-view="Membership">Open membership</button>
            </div>
          </div>
          <div class="build-phase-console-card">
            <span>Current version</span>
            <strong>${escapeHtml(tracker.version.split(" ")[0])}</strong>
            <small>${doneCount} done / ${activeCount} active / ${mostlyDoneCount} mostly done</small>
          </div>
        </section>
        ${renderProductBuildTracker(tracker)}
        ${renderBuildPhaseArtifactSections(commandModel)}
      </section>
    `;
  }

